package com.trampolim.api.hub;
import java.util.*;
import static com.trampolim.api.hub.HubRules.*;import static com.trampolim.api.radar.RadarModel.*;
import com.trampolim.api.security.PlatformAccess;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.web.server.ResponseStatusException;import org.springframework.transaction.annotation.Transactional;
@RestController
@RequestMapping("/api/admin/hub")
@ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class HubAdminController {
 private final HubService service;private final PlatformAccess platform;private final JdbcTemplate jdbc;
 public HubAdminController(HubService service,PlatformAccess platform,@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc){this.service=service;this.platform=platform;this.jdbc=jdbc;}
 private void admin(String email){if(!platform.isSuperAdmin(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Acesso restrito à administração geral.");}
 public record Create(String name,Profile profile,String type){public Create(String name,Profile profile){this(name,profile,"ASSOCIATION");}}public record State(String status){}public record Verification(String status,String note){}
 @GetMapping("/organizations")public Map<String,Object> list(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String q){admin(email);page(before,limit);text(q,120);return HubService.pageResult(jdbc.queryForList("SELECT id,name,organization_type,status,verification_status FROM enterprise_organizations WHERE organization_type IN ('ASSOCIATION','EDUCATIONAL') AND id<? AND (?='' OR name ILIKE ?) ORDER BY id DESC LIMIT ?",before,q,"%"+q+"%",limit+1),limit);}
 @PostMapping("/organizations")@Transactional("empresasTransactionManager")public Map<String,Object> create(@AuthenticationPrincipal String email,@RequestBody Create body){admin(email);if(body==null||text(body.name(),180).isEmpty())bad("Informe nome institucional.");String type=Objects.toString(body.type(),"ASSOCIATION");if(!Set.of("ASSOCIATION","EDUCATIONAL").contains(type))bad("Tipo institucional inválido.");HubRules.profile(body.profile());long id=jdbc.queryForObject("INSERT INTO enterprise_organizations(name,organization_type,status) VALUES (?,?,'PENDING') RETURNING id",Long.class,body.name().trim(),type);service.saveProfile(id,email,body.profile());service.audit(id,email,type.equals("EDUCATIONAL")?"EDUCATIONAL_INSTITUTION_CREATED":"HUB_ASSOCIATION_CREATED");return Map.of("id",id,"type",type,"status","PENDING","verificationStatus",type.equals("EDUCATIONAL")?"PENDING_REVIEW":"NOT_APPLICABLE");}
 @GetMapping("/organizations/{id}/profile")public Map<String,Object> profile(@AuthenticationPrincipal String email,@PathVariable long id){admin(email);return service.profile(id);}
 @PutMapping("/organizations/{id}/profile")public Map<String,Object> profile(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Profile body){admin(email);return service.saveProfile(id,email,body);}
 @PutMapping("/organizations/{id}/status")@Transactional("empresasTransactionManager")public Map<String,Object> state(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody State input){admin(email);service.exists(id);if(input==null||!Set.of("ACTIVE","PENDING","SUSPENDED").contains(Objects.toString(input.status(),"")))bad("Situação inválida.");var p=service.profile(id);boolean educational="EDUCATIONAL".equals(p.get("organization_type"));if(input.status().equals("ACTIVE")&&educational&&!"VERIFIED".equals(p.get("verification_status")))bad("Verifique a instituição pelo fluxo de revisão antes de ativar.");if(input.status().equals("ACTIVE")&&(Objects.toString(p.get("legal_name"),"").isBlank()||Objects.toString(p.get("contact_email"),"").isBlank()||Objects.toString(p.get("responsible_name"),"").isBlank()))bad("Preencha nome legal, contato e responsável antes de ativar o Hub.");jdbc.update("UPDATE enterprise_organizations SET status=?,verification_status=CASE WHEN organization_type='EDUCATIONAL' AND ?='PENDING' THEN 'PENDING_REVIEW' ELSE verification_status END,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.status(),input.status(),id);service.audit(id,email,educational?"EDUCATIONAL_INSTITUTION_STATUS_CHANGED":"HUB_ASSOCIATION_STATUS_CHANGED");return Map.of("status",input.status());}
 @PutMapping("/organizations/{id}/verification")@Transactional("empresasTransactionManager")public Map<String,Object> verify(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Verification input){admin(email);var profile=service.profile(id);if(!"EDUCATIONAL".equals(profile.get("organization_type")))bad("A verificação institucional se aplica a instituições de ensino.");if(input==null||!Set.of("PENDING_REVIEW","VERIFIED","REJECTED").contains(Objects.toString(input.status(),"")))bad("Situação de verificação inválida.");String note=text(input.note(),500);if(input.status().equals("REJECTED")&&note.isBlank())bad("Registre o motivo da reprovação para orientar a instituição.");if(input.status().equals("VERIFIED")&&(Objects.toString(profile.get("legal_name"),"").isBlank()||Objects.toString(profile.get("legal_identifier"),"").isBlank()||Objects.toString(profile.get("contact_email"),"").isBlank()||Objects.toString(profile.get("responsible_name"),"").isBlank()))bad("Revise nome legal, identificador institucional, contato e representante antes de verificar.");String nextOrganizationStatus=input.status().equals("VERIFIED")?"ACTIVE":"PENDING";jdbc.update("UPDATE enterprise_organizations SET verification_status=?,verification_note=?,verified_at=CASE WHEN ?='VERIFIED' THEN CURRENT_TIMESTAMP ELSE NULL END,verified_by=CASE WHEN ?='VERIFIED' THEN ? ELSE NULL END,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.status(),note,input.status(),input.status(),email,nextOrganizationStatus,id);jdbc.update("UPDATE hub_profiles SET published=FALSE,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND ?<>'VERIFIED'",id,input.status());service.audit(id,email,"EDUCATIONAL_INSTITUTION_VERIFICATION_"+input.status());return Map.of("status",nextOrganizationStatus,"verificationStatus",input.status());}
 @GetMapping("/organizations/{id}/companies")public Map<String,Object> companies(@AuthenticationPrincipal String email,@PathVariable long id,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit){admin(email);service.exists(id);return service.companies(id,before,limit);}
 @GetMapping("/plans")public List<Map<String,Object>> plans(@AuthenticationPrincipal String email){admin(email);return service.plans();}
 @PostMapping("/plans")public Map<String,Object> plan(@AuthenticationPrincipal String email,@RequestBody Plan input){admin(email);return service.plan(email,input);}
 @PutMapping("/plans/{id}/status")public void planState(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody State input){admin(email);if(input==null||!Set.of("ACTIVE","DRAFT","ARCHIVED").contains(Objects.toString(input.status(),"")))bad("Situação inválida.");if(jdbc.update("UPDATE hub_institutional_plans SET status=? WHERE id=?",input.status(),id)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);service.auditPlan(id,email,"HUB_PLAN_STATUS_CHANGED");}
 @GetMapping("/organizations/{id}/contracts")public List<Map<String,Object>> contracts(@AuthenticationPrincipal String email,@PathVariable long id){admin(email);service.exists(id);return service.contracts(id);}
 @PostMapping("/organizations/{id}/contracts")public Map<String,Object> contract(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Contract input){admin(email);return service.contract(id,0,email,input);}
 @PutMapping("/organizations/{id}/contracts/{cid}")public Map<String,Object> contract(@AuthenticationPrincipal String email,@PathVariable long id,@PathVariable long cid,@RequestBody Contract input){admin(email);return service.contract(id,cid,email,input);}
 @GetMapping("/organizations/{id}/usage")public Map<String,Object> usage(@AuthenticationPrincipal String email,@PathVariable long id){admin(email);return service.usage(id);}
}
